@app.route("/")
def index():
    html = SISTEMA_HTML
    if "np-contratos-toggle-admin-20260627" not in html:
        html = html.replace("</body>", CONTRACTS_TOGGLE_SCRIPT + "\n</body>")
    if "np-usuarios-servidor-20260803" not in html:
        html = html.replace("</body>", USER_SYNC_SCRIPT + "\n</body>")
    response = Response(html, mimetype="text/html; charset=utf-8")
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    return response


@app.route("/uploads/<path:name>")
def uploads(name):
    return send_file(UPLOAD_DIR / name)

@app.route("/api/config", methods=["GET","POST"])
def config():
    if request.method=="GET":
        cfg = load_config()
        safe = cfg.copy()
        if safe.get("openai_api_key"):
            safe["openai_api_key"] = "********" + safe["openai_api_key"][-4:]
        return jsonify(safe)
    data = request.json or {}
    cfg = load_config()
    for k in ["modelo","senha_gerente","nome_gerente_padrao","prompt_extra","regras_padrao","contratos_ativo"]:
        if k in data: cfg[k] = data[k]
    if data.get("openai_api_key") and not str(data["openai_api_key"]).startswith("********"):
        cfg["openai_api_key"] = data["openai_api_key"]
    save_config(cfg)
    return jsonify({"ok":True})

@app.route("/api/usuarios", methods=["GET","POST"])
def usuarios_api():
    if request.method == "GET":
        return jsonify({"ok": True, "usuarios": load_users()})
    data = request.json or {}
    usuarios = data.get("usuarios", [])
    if not isinstance(usuarios, list):
        return jsonify({"ok": False, "erro": "Lista de usuários inválida."}), 400
    return jsonify({"ok": True, "usuarios": save_users(usuarios)})

@app.route("/api/analisar", methods=["POST"])
def analisar():
    try:
        contrato = request.files.get("contrato")
        docs = request.files.getlist("documentos")
        tipo = request.form.get("tipo_assinatura","automatico")
        vendedor = (request.form.get("vendedor") or request.form.get("vendor") or "").strip()
        vendedor_login = (request.form.get("vendedor_login") or request.form.get("vendor_login") or "").strip()
        if not contrato:
            return jsonify({"ok":False,"erro":"Anexe o contrato principal."}),400
        if not docs or all(not d.filename for d in docs):
            return jsonify({"ok":False,"erro":"Documento complementar é obrigatório."}),400
        contract_path = save_upload(contrato, "contrato")
        doc_paths = [save_upload(d,"doc") for d in docs if d and d.filename]
        doc_paths = [p for p in doc_paths if p]
        doc_names = [Path(p).name for p in doc_paths]
        gate = quick_contract_gate(str(contract_path))

        cfg = load_config()
        if cfg.get("openai_api_key") and OpenAI:
            try:
                client = OpenAI(
                    api_key=cfg["openai_api_key"],
                    http_client=httpx.Client(trust_env=False, timeout=90),
                )
                resp = client.chat.completions.create(
                    model=cfg.get("modelo","gpt-4o-mini"),
                    messages=build_messages(str(contract_path), [str(p) for p in doc_paths], tipo),
                    temperature=0.02,
                    response_format={"type":"json_object"}
                )
                result = json.loads(resp.choices[0].message.content)
            except Exception as e:
                result = fallback(str(contract_path), [str(p) for p in doc_paths], tipo, gate)
                result["erro_ia"] = str(e)
        else:
            result = fallback(str(contract_path), [str(p) for p in doc_paths], tipo, gate)
            result["erro_ia"] = "OpenAI API Key não configurada nesta pasta/versão. Salve a chave em Configurações para análise completa."

        contract_text_for_quality = extract_text_from_pdf(str(contract_path)) if Path(contract_path).suffix.lower() == ".pdf" else ""
        has_photo_page = contract_has_extra_photo_page(str(contract_path))
        result["contrato_tem_pagina_de_foto"] = has_photo_page
        result = normalize_result(result, gate, doc_names, contract_text_for_quality, has_photo_page)
        result = _merge_missing_summary(result, Path(contract_path))
        result["previews_contrato"] = preview_images(str(contract_path), "preview_contrato")
        result["previews_documentos"] = []
        for p in doc_paths:
            result["previews_documentos"].extend(preview_images(str(p), "preview_doc")[:2])
        result["vendedor"] = vendedor or "Não informado"
        result["vendor"] = vendedor or "Não informado"
        result["contrato_tem_pagina_de_foto"] = has_photo_page
        result = apply_document_quality_guard(result, doc_names, contract_text_for_quality, has_photo_page)
        result["vendedor_login"] = vendedor_login
        result["vendor_login"] = vendedor_login
        result["data_hora"] = datetime.datetime.now().strftime("%d/%m/%Y %H:%M:%S")
        result["id"] = datetime.datetime.now().strftime("%Y%m%d%H%M%S")
        hist = load_history()
        hist.insert(0,result)
        save_history(hist[:200])
        return jsonify({"ok":True,"resultado":result})
    except Exception as e:
        return jsonify({"ok":False,"erro":str(e)}),500

@app.route("/api/aprovacao-gerencial", methods=["POST"])
def aprovacao_gerencial():
    data = request.json or {}
    cfg = load_config()
    if data.get("senha") != cfg.get("senha_gerente"):
        return jsonify({"ok":False,"erro":"Senha gerencial inválida."}),403
    just = (data.get("justificativa") or "").strip()
    gerente = (data.get("gerente") or cfg.get("nome_gerente_padrao") or "Gerente").strip()
    if len(just) < 15:
        return jsonify({"ok":False,"erro":"Informe justificativa detalhada."}),400
    rid = data.get("id")
    hist = load_history()
    item = next((x for x in hist if x.get("id")==rid), None)
    if not item:
        return jsonify({"ok":False,"erro":"Registro não encontrado."}),404
    item["aprovacao_gerencial"] = {
        "status":"APROVADO_POR_EXCECAO",
        "gerente":gerente,
        "justificativa":just,
        "data_hora":datetime.datetime.now().strftime("%d/%m/%Y %H:%M:%S")
    }
    item["status_final"] = "APROVADO_POR_EXCECAO"
    save_history(hist)
    return jsonify({"ok":True,"resultado":item})

@app.route("/api/historico")
def historico():
    return jsonify(load_history())

if os.environ.get("NETPRIME_DISABLE_BACKUP", "0") != "1":
    start_background_services()

if __name__ == "__main__":
    url = "http://127.0.0.1:5000/"
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as probe:
        already_running = probe.connect_ex(("127.0.0.1", 5000)) == 0
    if already_running:
        webbrowser.open(url)
    else:
        print(f"Sistema NetPrime unificado iniciado em {url}")
        print("Operacao principal: com OpenAI API Key salva em Configuracoes.")
        print("Sem chave, o sistema entra em revisao manual/fallback.")
        threading.Timer(1.2, lambda: webbrowser.open(url)).start()
        app.run(debug=False, port=5000, use_reloader=False)


